// ColorButton — Gtk.ColorButton
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles colorbutton with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ColorButtonProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.ColorButton */
  modal?: boolean

  /** gboolean, from Gtk.ColorButton */
  showEditor?: boolean

  /** utf8, from Gtk.ColorButton */
  title?: string
}

export function ColorButton({ className, children, title }: ColorButtonProps) {
  return (
    <div className={cn(className)}>
      {title}
      {children}
    </div>
  )
}
